<?php require __DIR__.'/app/bootstrap.php';$u=require_user(false);require_commerce();$title=t('My orders');$orders=all('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC',[$u['id']]);require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="page-heading"><span class="heading-kicker"><?=e(t('YOUR FOOD JOURNEY'))?></span><h1><?=e(t('My Orders'))?></h1><p><?=e(t('Pickup and delivery orders, all in one place.'))?></p></div><?php if(!$orders): ?><div class="panel empty"><h2><?=e(t('Your first order is waiting.'))?></h2><a class="pill primary" href="<?=e(url('index.php'))?>"><?=e(t('Explore Food →'))?></a></div><?php else: ?><div class="saved-grid"><?php foreach($orders as $order): ?><article class="panel padded"><div class="order-meta"><span class="chip"><?=e(status_label($order))?></span><span><?=e(t(ucfirst($order['fulfillment'])))?></span></div><h2><?=e($order['shop_name'])?></h2><p class="hint"><?=e($order['reference'])?> · <?=e(local_time($order['created_at']))?></p><p><strong><?=money((int)$order['total_paisa'])?></strong><br><small><?=e(t('Delivery:'))?> <?=money((int)$order['delivery_fee_paisa'])?></small></p><a class="pill" href="<?=e(url('order.php?id='.$order['id']))?>"><?=e(t('View Order →'))?></a></article><?php endforeach ?></div><?php endif ?></main><?php require ROOT.'/app/footer.php'; ?>
